 oldrows=[y for y in prior if all(y[k]==x[k] for k in ('benchmark','scenario','boundary','metric','unit','contract_sha256','cohort'))];on=[y for y in oldrows if y['engine']=='nift'];op=[y for y in oldrows if y['engine']!='nift'];previous=f"{on[0]['value']/min(y['value'] for y in op):.1f}× (cross-node)" if on and op else 'not retained in normalized peer exports'
